// x509_ref_smoke — crypto/x509 certificate parsing against a running
// Go. (crypto/x509/parser.go, crypto/x509/x509.go)
//
// Every expectation below is what a real Go 1.25.5 prints: the lines in
// GO are the verbatim output of `tools/gen_x509_ref.go` run in
// `package x509_test` by `scripts/goref.sh`. The CERTIFICATES are built
// by that run and embedded here as DER, so goish parses the same bytes
// — parsing a certificate produced by the same code tests the round
// trip rather than the parser, and the interesting inputs are the ones
// with awkward extensions rather than the ones a happy path emits.
//
// crypto/x509 parses certificates that arrive from whoever is at the
// other end of a connection. Every field it reports is one a caller may
// make a trust decision on, so a field parsed slightly wrong is a trust
// decision made slightly wrong — and the ones that matter most are the
// ones nobody looks at until they do.
//
// goish matched Go on all 88 lines, across ten certificates and seven
// malformed inputs. What is pinned:
//
//   * Every SAN kind: DNS names including a wildcard, email addresses,
//     IPv4 AND IPv6 addresses, and a URI. The IP case matters twice
//     over, because net.IP's own 4-vs-16-byte handling was wrong until
//     faf2387 and a SAN is where the two packages meet.
//   * BasicConstraints in all three shapes — absent, CA with a path
//     length, and CA with an explicit zero path length, where
//     MaxPathLen 0 and MaxPathLenZero true mean something different
//     from MaxPathLen 0 with the flag false.
//   * KeyUsage as a bitmask and ExtKeyUsage as a list.
//   * Name constraints: permitted and excluded DNS domains, permitted
//     and excluded IP ranges, and permitted email addresses — the
//     extension that decides which names a CA is allowed to vouch for,
//     and therefore the one where a parse error is a trust failure.
//   * The full subject: country, organization, OU, locality, province,
//     street, postal code and serial, including a UTF-8 CommonName.
//   * A serial number past 2^120, which does not fit an int64.
//   * Seven malformed DER inputs and the exact message each produces.

#![no_std]
#![no_main]
#![allow(non_snake_case)]

extern crate alloc;
extern crate goish;

use goish::crypto::x509;
use goish::fmt;
use goish::goslice::slice;
use goish::gostring::string;
use goish::syscall;
use goish::time;
use goish::types::{byte, int};

fn s(x: &str) -> string {
    return string::from_bytes(x.as_bytes());
}
fn unhex(h: &str) -> alloc::vec::Vec<u8> {
    let b = h.as_bytes();
    let mut out: alloc::vec::Vec<u8> = alloc::vec::Vec::with_capacity(b.len() / 2);
    let mut i = 0usize;
    while i + 1 < b.len() {
        let hi = (b[i] as char).to_digit(16).unwrap_or(0) as u8;
        let lo = (b[i + 1] as char).to_digit(16).unwrap_or(0) as u8;
        out.push((hi << 4) | lo);
        i += 2;
    }
    return out;
}
// Go prints a []string as [a b] with no quotes; match that.
fn list(v: &slice<string>) -> string {
    let mut o = s("[");
    for i in 0..v.Len() {
        if i > 0 {
            o = o + s(" ");
        }
        o = o + v[i].clone();
    }
    return o + s("]");
}
// The certificates are BUILT by Go and embedded as DER, so goish parses
// the same bytes; parsing a certificate produced by the same code tests
// the round trip rather than the parser.
const CERTS: [(&str, &str); 11] = [
    ("minimal", ""),
    ("full-subject", ""),
    ("sans", ""),
    ("ca", ""),
    ("ca-pathlen-zero", ""),
    ("eku", ""),
    ("name-constraints", ""),
    ("ecdsa", ""),
    ("big-serial", ""),
    ("utf8-subject", ""),
    ("bad-source", ""),
];

