// go: none — goish idiom: one comparison, printing the divergence when
//     it is one, so a FAIL says what it got and not just that it did.
fn chk(failed: &mut int, ln: &mut int, got: string) {
    if *ln >= GO.len() as int {
        fmt::Printf!("[!!] extra line %d: %q\n", *ln + 1, got);
        *failed += 1;
        *ln += 1;
        return;
    }
    let want = s(GO[*ln as usize]);
    *ln += 1;
    if got == want {
        return;
    }
    fmt::Printf!("[!!] line %d FAIL\n  got  %q\n  want %q\n", *ln, got, want);
    *failed += 1;
}

#[goish::main]
fn main() {
    let mut failed: int = 0;
    let mut ln: int = 0;

    for (name, hexs) in CERTS.iter() {
        if *name == "bad-source" {
            continue;
        }
        let der = unhex(hexs);
        chk(
            &mut failed,
            &mut ln,
            fmt::Sprintf!("der %-17s hex=%s", s(name), s(hexs)),
        );
        dump(&mut failed, &mut ln, s(name), slice::__from_vec(der));
    }
    {
        let good = unhex(CERTS[CERTS.len() - 1].1);
        chk(
            &mut failed,
            &mut ln,
            fmt::Sprintf!(
                "der %-17s hex=%s",
                s("bad-source"),
                s(CERTS[CERTS.len() - 1].1)
            ),
        );
        let mut one = good.clone();
        one.truncate(1);
        let mut half = good.clone();
        half.truncate(good.len() / 2);
        let mut last = good.clone();
        last.truncate(good.len() - 1);
        let mut junk = good.clone();
        junk.push(0);
        let cases: [(&str, alloc::vec::Vec<u8>); 7] = [
            ("empty", alloc::vec::Vec::new()),
            ("one-byte", one),
            ("truncated-half", half),
            ("truncated-last", last),
            ("trailing-junk", junk),
            ("all-zero", alloc::vec![0u8; 32]),
            ("not-a-cert", alloc::vec![0x30u8, 0x03, 0x02, 0x01, 0x01]),
        ];
        for (n, d) in cases.iter() {
            let (_, err) = x509::ParseCertificate(slice::__from_vec(d.clone()));
            if !err.IsNil() {
                chk(
                    &mut failed,
                    &mut ln,
                    fmt::Sprintf!("parsebad %-16s -> err=%q", s(n), err.Error()),
                );
                continue;
            }
            chk(
                &mut failed,
                &mut ln,
                fmt::Sprintf!("parsebad %-16s -> ok", s(n)),
            );
        }
    }
    let _: byte = 0;
    if ln != GO.len() as int {
        fmt::Printf!("[!!] produced %d lines, pinned %d\n", ln, GO.len() as int);
        failed += 1;
    }
    if failed == 0 {
        fmt::Printf!("ok %d/%d\n", ln, ln);
        return;
    }
    fmt::Printf!("FAILED %d of %d\n", failed, ln);
    syscall::Exit(1);
}

fn dump(failed: &mut int, ln: &mut int, name: string, der: slice<byte>) {
    let (c, err) = x509::ParseCertificate(der);
    if !err.IsNil() {
        chk(
            failed,
            ln,
            fmt::Sprintf!("cert %-17s parse-err=%q", name, err.Error()),
        );
        return;
    }
    chk(
        failed,
        ln,
        fmt::Sprintf!(
            "cert %-17s ver=%d serial=%s sigalg=%v pkalg=%v cn=%q issuer-cn=%q",
            name.clone(),
            c.Version,
            c.SerialNumber.String(),
            c.SignatureAlgorithm.String(),
            c.PublicKeyAlgorithm.String(),
            c.Subject.CommonName.clone(),
            c.Issuer.CommonName.clone()
        ),
    );
    chk(
        failed,
        ln,
        fmt::Sprintf!(
            "subj %-17s c=%s o=%s ou=%s l=%s p=%s street=%s pc=%s sn=%q",
            name.clone(),
            list(&c.Subject.Country),
            list(&c.Subject.Organization),
            list(&c.Subject.OrganizationalUnit),
            list(&c.Subject.Locality),
            list(&c.Subject.Province),
            list(&c.Subject.StreetAddress),
            list(&c.Subject.PostalCode),
            c.Subject.SerialNumber.clone()
        ),
    );
    chk(
        failed,
        ln,
        fmt::Sprintf!(
            "time %-17s nb=%s na=%s",
            name.clone(),
            c.NotBefore.UTC().Format(time::RFC3339),
            c.NotAfter.UTC().Format(time::RFC3339)
        ),
    );
    let mut uris = s("[");
    for i in 0..c.URIs.Len() {
        if i > 0 {
            uris = uris + s(" ");
        }
        uris = uris + c.URIs[i].String();
    }
    uris = uris + s("]");
    let mut ips = s("[");
    for i in 0..c.IPAddresses.Len() {
        if i > 0 {
            ips = ips + s(" ");
        }
        ips = ips + c.IPAddresses[i].String();
    }
    ips = ips + s("]");
    chk(
        failed,
        ln,
        fmt::Sprintf!(
            "san  %-17s dns=%s email=%s ip=%s uri=%s",
            name.clone(),
            list(&c.DNSNames),
            list(&c.EmailAddresses),
            ips,
            uris
        ),
    );
    let mut eku = s("[");
    for i in 0..c.ExtKeyUsage.Len() {
        if i > 0 {
            eku = eku + s(" ");
        }
        eku = eku + fmt::Sprintf!("%d", c.ExtKeyUsage[i].0);
    }
    eku = eku + s("]");
    chk(
        failed,
        ln,
        fmt::Sprintf!(
            "use  %-17s isca=%-5v bcvalid=%-5v pathlen=%d pathlenzero=%v ku=%d eku=%s",
            name.clone(),
            c.IsCA,
            c.BasicConstraintsValid,
            c.MaxPathLen,
            c.MaxPathLenZero,
            c.KeyUsage.0,
            eku
        ),
    );
    let mut pip = s("[");
    for i in 0..c.PermittedIPRanges.Len() {
        if i > 0 {
            pip = pip + s(" ");
        }
        pip = pip + c.PermittedIPRanges[i].String();
    }
    pip = pip + s("]");
    let mut eip = s("[");
    for i in 0..c.ExcludedIPRanges.Len() {
        if i > 0 {
            eip = eip + s(" ");
        }
        eip = eip + c.ExcludedIPRanges[i].String();
    }
    eip = eip + s("]");
    chk(
        failed,
        ln,
        fmt::Sprintf!(
            "nc   %-17s crit=%-5v pdns=%s edns=%s pip=%s eip=%s pmail=%s",
            name.clone(),
            c.PermittedDNSDomainsCritical,
            list(&c.PermittedDNSDomains),
            list(&c.ExcludedDNSDomains),
            pip,
            eip,
            list(&c.PermittedEmailAddresses)
        ),
    );
    chk(
        failed,
        ln,
        fmt::Sprintf!("ext  %-17s n=%d", name, c.Extensions.Len()),
    );
}
